; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch1_e_go:			ld sp, ch1_e
			jp ntc_xn
ch2_e_go:			ld sp, ch2_e
			jp ntc_xn
ch3_e_go:			ld sp, ch3_e
			jp ntc_xn
ch4_e_go:			ld sp, ch4_e
			jp ntc_xn
ch6_e_go:			ld sp, ch6_e
			jp ntc_xn
ch7_e_go:			ld sp, ch7_e
			jp ntc_xn
ch8_e_go:			ld sp, ch8_e
			jp ntc_xn
if10_e_go:			ld sp, if10_e
			jp ntc_xn
if11_e_go:			ld sp, if11_e
			jp ntc_xn
if12_e_go:			ld sp, if12_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld de, var_chk_got		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; want
			ldi
			ldi
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chkl_c:		; call chkl (normal)
			pop hl			; got
			ld de, var_chkl_got
			ld bc, 4
			ldir
			pop hl			; want
			ld de, var_chkl_want
			ld bc, 4
			ldir
			ld (p_chkl_rs), sp
			ld sp, p_chkl
			jp ntc_xn
p_chkl_r:		; end of chkl
			ld sp, (p_chkl_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn

